import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { GrammarError, GrammarLevel, GrammarMood, GrammarScene } from '../types'
import { isIgnored, marks, parseErrors, pick, proseOf } from './logic'
import { ASCII, mascot } from './mascot'

const isOn = atom({ plugin: 'grammar-police', key: 'isOn' } as const, true)
const level = atom({ plugin: 'grammar-police', key: 'level' } as const, 'chill')
const scene = atom({ plugin: 'grammar-police', key: 'scene' } as const, null)

const NAME = 'Sgt. Apostrophe'

const LINES = {
  one: [
    'Freeze! Hands where I can see your keyboard.',
    'One tiny crime. I saw it. I always see it.',
    'Ahem. Fix this one, and we never speak of it again.',
    'Halt, citizen! Your sentence needs a sentence.',
  ],
  many: [
    '{n} crimes in one prompt? Bold. Very bold.',
    'My whistle is tired. So am I.',
    'Step away from the Enter key. Slowly.',
  ],
  shocked: [
    'This is not a prompt. This is a crime scene. 🚧',
    'Backup! I need backup! 📻',
    'I have to sit down for this one.',
  ],
  repeat: [
    'You again?! I am starting a file on you. 📁',
    'Strike {rap}. My donut is getting cold.',
    'We have to stop meeting like this.',
  ],
  cleared: [
    'Clean as a whistle. You may pass! ✨',
    'Beautiful. I might cry. 🥲',
    'Case closed. Good citizen!',
    'Now THAT is English. Carry on.',
  ],
  offDuty: ['Fine. Donut break. 🍩 Call me back with /grammar.', 'Off duty. Nobody saw anything. 😴'],
  onDuty: ['Sgt. Apostrophe, reporting for duty! 🫡', 'I am back. And I brought my whistle.'],
  medal: ['{n} clean prompts in a row! The Medal of Grammar is yours! 🏅'],
}

const RULES: Record<GrammarLevel, string> = {
  chill:
    'Flag only clear spelling typos, wrong words, a missing or wrong verb form, ' +
    'subject-verb agreement, a missing apostrophe in a contraction, and a lowercase "i" as a pronoun. ' +
    'Do not flag capital letters at the start of a sentence, punctuation, or a missing article.',
  strict:
    'Flag every spelling typo, grammar error, wrong or missing article, wrong preposition, ' +
    'missing capital letter, and missing apostrophe.',
}

const SYSTEM =
  'You are a strict but fair English proofreader for a non-native speaker who wants to improve. ' +
  "You check only the writer's own English prose. " +
  'Ignore code, shell commands, file paths, identifiers, URLs, names of products and tools, ' +
  'names of people, projects, companies, and places, even when you do not know them, ' +
  'text inside backticks or quotes, and pasted logs or documents. ' +
  'Do not flag casual tone, informal words, chat style, a sentence fragment, or a missing final period. ' +
  'Answer with JSON only, no prose and no code fence: ' +
  '{"errors":[{"wrong":"<the smallest exact substring of the text that is wrong>",' +
  '"right":"<the fix for that substring>","why":"<at most 8 words>"}]}. ' +
  'Each "wrong" value must appear in the text exactly, character for character. ' +
  'When the text has no error, answer {"errors":[]}.'

// The person's own prompt, from the terminal, the desktop app, or a phone.
const PERSON = new Set(['composer', 'bridge', 'sdk'])

// How long a scene stays before it leaves by itself. An arrest stays until the prompt is clean.
const SCENE_MS: Record<GrammarMood, number> = {
  arrest: 0,
  shocked: 0,
  happy: 5000,
  sleepy: 5000,
  medal: 7000,
}

const BORDER: Record<GrammarMood, string> = {
  arrest: 'red',
  shocked: 'red',
  happy: 'green',
  sleepy: 'gray',
  medal: 'yellow',
}

async function readIgnored($: EngineInterface): Promise<string[]> {
  const value = await $.store.get('ignored')
  return Array.isArray(value) ? value.filter((one): one is string => typeof one === 'string') : []
}

async function addIgnored($: EngineInterface, word: string) {
  const one = word.trim().toLowerCase()
  const list = await readIgnored($)
  if (one !== '' && !list.includes(one)) await $.store.set('ignored', [...list, one].sort())
}


async function showStatus($: EngineInterface) {
  const isOnDuty = await read($, isOn)
  $.ui.status(isOnDuty ? `👮 ${NAME}: on duty (${await read($, level)})` : undefined)
}

async function play(
  $: EngineInterface,
  mood: GrammarMood,
  line: string,
  errors: GrammarError[] = [],
  arrest = 0,
  ms = SCENE_MS[mood],
  text = '',
) {
  const id = Date.now() * 1000 + Math.floor(Math.random() * 1000)
  await update($, scene, () => ({ id, mood, line, errors, arrest, text }))
  if (ms > 0) {
    $.clock.after(ms, () => {
      void update($, scene, now => (now?.id === id ? null : now))
    })
  }
}

// Send the blocked prompt with no check: the plugin's own prompt skips the check.
// The box wins over the stored text, so an edit the person made is kept.
async function sendAnyway($: EngineInterface, stored: string) {
  const box = await $.prompt.read()
  const text = box.text.trim() !== '' ? box.text : stored
  await update($, scene, () => null)
  await $.prompt.fill({ text: '', mode: 'replace' })
  await $.prompt.submit({ text, asUser: true })
}

// "Not a mistake": the word goes in the dictionary. With no charge left, the prompt goes.
async function notMistake($: EngineInterface, wrong: string) {
  await addIgnored($, wrong)
  const now = await read($, scene)
  if (now === null) return
  const left = now.errors.filter(one => one.wrong !== wrong)
  if (left.length > 0) {
    await update($, scene, current => (current === null ? null : { ...current, errors: left }))
    return
  }
  await sendAnyway($, now.text)
}

async function setOn($: EngineInterface, value: boolean) {
  await update($, isOn, () => value)
  await $.store.set('isOn', value)
  await showStatus($)
  await play($, value ? 'happy' : 'sleepy', pick(value ? LINES.onDuty : LINES.offDuty))
}

export const register: Register = (on, options) => {
  const model = typeof options.model === 'string' && options.model.trim() !== '' ? options.model : 'haiku'

  on('session.start', async ($, e, next) => {
    const storedOn = await $.store.get('isOn')
    const storedLevel = await $.store.get('level')
    if (typeof storedOn === 'boolean') await update($, isOn, () => storedOn)
    if (storedLevel === 'chill' || storedLevel === 'strict') {
      await update($, level, () => storedLevel)
    }
    await $.command.register({
      name: 'grammar',
      description: `${NAME}: toggle, set the patrol, or keep your own dictionary`,
      argumentHint: '[on | off | chill | strict | stats | ignore <word> | unignore <word> | ignored]',
      immediate: true,
    })
    await showStatus($)
    return next(e)
  })

  on('command.run', { command: 'grammar' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    const [verb = '', ...rest] = arg.split(/\s+/)
    const word = rest.join(' ')

    if (verb === 'ignore' || verb === 'unignore') {
      if (word === '') return { text: `👮 Name the word: /grammar ${verb} <word>` }
      if (verb === 'ignore') await addIgnored($, word)
      else await $.store.set('ignored', (await readIgnored($)).filter(one => one !== word))
      return {
        text:
          verb === 'ignore'
            ? `👮 "${word}" is in your dictionary. ${NAME} will not flag it again.`
            : `👮 "${word}" left your dictionary.`,
      }
    }

    if (verb === 'ignored') {
      const list = await readIgnored($)
      return {
        text:
          list.length === 0
            ? '👮 Your dictionary is empty.'
            : `👮 Your dictionary (${list.length}): ${list.join(', ')}`,
      }
    }

    if (arg === 'stats') {
      const arrests = Number((await $.store.get('arrests')) ?? 0)
      const streak = Number((await $.store.get('streak')) ?? 0)
      const best = Number((await $.store.get('best')) ?? 0)
      return {
        text: `👮 Your file: ${arrests} arrests. Clean streak: ${streak} prompts (best ${best}).`,
      }
    }

    if (arg === 'chill' || arg === 'strict') {
      await update($, level, () => arg)
      await $.store.set('level', arg)
      await update($, isOn, () => true)
      await $.store.set('isOn', true)
      await showStatus($)
      await play(
        $,
        arg === 'strict' ? 'arrest' : 'happy',
        arg === 'strict'
          ? 'Strict patrol. Every typo, article, capital letter, and apostrophe. 🧐'
          : 'Chill patrol. Only the clear crimes. 😎',
        [],
        0,
        5000,
      )
      return { text: `👮 ${NAME}: ${arg} patrol.` }
    }

    const value = arg === 'on' ? true : arg === 'off' ? false : !(await read($, isOn))
    await setOn($, value)
    return { text: value ? `👮 ${NAME} is on duty.` : `🍩 ${NAME} is off duty.` }
  })

  on('prompt.submit', async ($, e, next) => {
    const text = e.text.trim()
    const isPerson = PERSON.has(e.origin.kind)
    const isCommand = text.startsWith('/') || text.startsWith('!')
    if (!isPerson || isCommand || !(await read($, isOn))) return next(e)

    // No surface means no person to fix the prompt: a `claude -p` script or an SDK tool.
    if ((await $.session.surfaces()).length === 0) return next(e)

    const prose = proseOf(e.text)
    if (prose === '') return next(e)

    $.ui.status(`🔍 ${NAME} inspects your prompt…`)
    const ignored = await readIgnored($)
    const dictionary =
      ignored.length > 0
        ? `\n\nNever flag these words or phrases. They are correct for this writer: ${ignored.join(', ')}.`
        : ''
    let found: GrammarError[] | null = null
    try {
      const reply = await $.model.complete({
        model,
        system: SYSTEM,
        prompt: `${RULES[await read($, level)]}${dictionary}\n\nThe text:\n<<<\n${prose}\n>>>`,
        maxTokens: 1200,
        timeoutMs: 10000,
      })
      found = reply.isAnswered ? parseErrors(reply.text, e.text) : null
    } catch {
      // The engine refused the request (a blocked model, for one): the prompt passes.
      found = null
    } finally {
      await showStatus($)
    }

    const errors = found === null ? null : found.filter(one => !isIgnored(one, ignored))
    if (errors === null) {
      $.ui.toast(`☕ ${NAME} is on a coffee break. You may pass.`)
      return next(e)
    }

    if (errors.length === 0) {
      const now = await read($, scene)
      const wasBlocked = now !== null && now.errors.length > 0
      const streak = Number((await $.store.get('streak')) ?? 0) + 1
      const best = Math.max(streak, Number((await $.store.get('best')) ?? 0))
      await $.store.set('streak', streak)
      await $.store.set('best', best)
      await $.store.set('rap', 0)
      if (streak % 10 === 0) await play($, 'medal', pick(LINES.medal, { n: streak }))
      else if (wasBlocked) await play($, 'happy', pick(LINES.cleared))
      return next(e)
    }

    const arrest = Number((await $.store.get('arrests')) ?? 0) + 1
    const rap = Number((await $.store.get('rap')) ?? 0) + 1
    await $.store.set('arrests', arrest)
    await $.store.set('rap', rap)
    await $.store.set('streak', 0)

    const n = errors.length
    const mood: GrammarMood = n >= 4 ? 'shocked' : 'arrest'
    const line =
      rap >= 3
        ? pick(LINES.repeat, { rap })
        : n >= 4
          ? pick(LINES.shocked)
          : n >= 2
            ? pick(LINES.many, { n })
            : pick(LINES.one)
    await play($, mood, line, errors, arrest, SCENE_MS[mood], e.text)

    // Give the prompt back, with each crime underlined in red.
    $.clock.after(120, () => {
      void $.prompt.fill({ text: e.text, mode: 'replace', decorations: marks(e.text, errors) })
    })

    // The app always shows its own card for a block; the band below holds the rest.
    return { drop: '👮' }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const now = await read($, scene)
    if (e.props.hasSurvey || now === null) return next(e)

    const isCrime = now.errors.length > 0
    const charges = now.errors.map(one => ({ ...one }))
    const close = () => update($, scene, () => null)

    if (e.surface === 'desktop') {
      const { Box, Button, Svg, Text } = $.ui.resolve(e)
      return (
        <Box flexDirection="row" gap={2} borderStyle="round" borderColor={BORDER[now.mood]} paddingX={1}>
          <Svg source={mascot(now.mood, now.id)} alt={`${NAME}, ${now.mood}`} width={112} height={105} isInteractive />
          <Box flexDirection="column" flexShrink={1} gap={0}>
            <Text dimColor>
              👮 {NAME}
              {isCrime ? ` · arrest #${now.arrest}` : ''}
            </Text>
            <Text bold color={BORDER[now.mood] === 'gray' ? undefined : BORDER[now.mood]}>
              “{now.line}”
            </Text>
            {charges.map((one, i) => (
              <Box gap={1} alignItems="center">
                <Text color="red" strikethrough>
                  {one.wrong}
                </Text>
                <Text>→</Text>
                <Text color="green" bold>
                  {one.right}
                </Text>
                <Text dimColor>{one.why}</Text>
                <Button
                  key={`ignore-${i}`}
                  label="Not a mistake"
                  hotkey={i < 9 ? String(i + 1) : undefined}
                  onPress={() => notMistake($, one.wrong)}
                />
              </Box>
            ))}
            <Box gap={2}>
              <Button key="dismiss" label={isCrime ? 'Dismiss' : 'Bye!'} hotkey="d" role="dismiss" onPress={close} />
              {isCrime && <Button key="send" label="Send anyway" hotkey="s" onPress={() => sendAnyway($, now.text)} />}
              {isCrime && (
                <Button key="off" label="Off duty (I am in a rush)" hotkey="o" onPress={() => setOn($, false)} />
              )}
            </Box>
          </Box>
        </Box>
      )
    }

    const { Box, Button, Text } = $.ui.resolve(e)
    return (
      <Box flexDirection="row" gap={2} borderStyle="round" borderColor={BORDER[now.mood]} paddingX={1}>
        <Box flexDirection="column">
          {ASCII[now.mood].map(row => (
            <Text color={BORDER[now.mood]}>{row}</Text>
          ))}
        </Box>
        <Box flexDirection="column" flexShrink={1}>
          <Text dimColor>
            {NAME}
            {isCrime ? ` · arrest #${now.arrest}` : ''}
          </Text>
          <Text bold>“{now.line}”</Text>
          {charges.map((one, i) => (
            <Box gap={1}>
              <Text color="red" strikethrough>
                {one.wrong}
              </Text>
              <Text>→</Text>
              <Text color="green" bold>
                {one.right}
              </Text>
              <Text dimColor>{one.why}</Text>
              <Button
                key={`ignore-${i}`}
                label="Not a mistake"
                hotkey={i < 9 ? String(i + 1) : undefined}
                onPress={() => notMistake($, one.wrong)}
              />
            </Box>
          ))}
          <Box gap={2}>
            <Button key="dismiss" label={isCrime ? 'Dismiss' : 'Bye!'} hotkey="d" onPress={close} />
            {isCrime && <Button key="send" label="Send anyway" hotkey="s" onPress={() => sendAnyway($, now.text)} />}
            {isCrime && <Button key="off" label="Off duty" hotkey="o" onPress={() => setOn($, false)} />}
          </Box>
        </Box>
      </Box>
    )
  })
}

