import type { GrammarError } from '../types'

// The pure parts of the mod: no `$`, so the tests import them directly.

// The model reads at most this much prose of a prompt.
export const PROSE_LIMIT = 2000

// The writer's own prose: no code blocks, no quoted lines, no more than PROSE_LIMIT characters.
export function proseOf(text: string): string {
  return text
    .replace(/```[\s\S]*?(```|$)/g, ' ')
    .split('\n')
    .filter(row => !row.trimStart().startsWith('>'))
    .join('\n')
    .trim()
    .slice(0, PROSE_LIMIT)
}

export function pick(list: string[], values: Record<string, number> = {}): string {
  const line = list[Math.floor(Math.random() * list.length)] ?? ''
  return line.replace(/\{(\w+)\}/g, (_, key: string) => String(values[key] ?? ''))
}

export function parseErrors(reply: string, text: string): GrammarError[] | null {
  const start = reply.indexOf('{')
  const end = reply.lastIndexOf('}')
  if (start < 0 || end <= start) return null
  try {
    const parsed = JSON.parse(reply.slice(start, end + 1)) as { errors?: unknown }
    if (!Array.isArray(parsed.errors)) return null
    return (parsed.errors as Partial<GrammarError>[]).flatMap(one => {
      const { wrong, right, why } = one ?? {}
      const isValid =
        typeof wrong === 'string' &&
        typeof right === 'string' &&
        wrong.length > 0 &&
        wrong !== right &&
        text.includes(wrong)
      return isValid ? [{ wrong, right, why: String(why ?? '') }] : []
    })
  } catch {
    return null
  }
}

// The words the writer marked as correct, in lowercase.
export function isIgnored(one: GrammarError, ignored: readonly string[]): boolean {
  return ignored.includes(one.wrong.trim().toLowerCase())
}

export function marks(text: string, errors: GrammarError[]) {
  let from = 0
  return errors.flatMap(one => {
    let at = text.indexOf(one.wrong, from)
    if (at < 0) at = text.indexOf(one.wrong)
    if (at < 0) return []
    from = at + one.wrong.length
    return [{ start: at, end: at + one.wrong.length, color: 'red', underline: true, bold: true }]
  })
}

