export type GrammarError = { wrong: string; right: string; why: string }

export type GrammarLevel = 'chill' | 'strict'

export type GrammarMood = 'arrest' | 'shocked' | 'happy' | 'sleepy' | 'medal'

export type GrammarScene = {
  id: number
  mood: GrammarMood
  line: string
  errors: GrammarError[]
  arrest: number
  /** The blocked prompt, so that a press can send it without a check. */
  text: string
}

declare module 'claude-code' {
  interface PluginState {
    'grammar-police': {
      isOn: boolean
      level: GrammarLevel
      scene: GrammarScene | null
    }
  }
}
